pub fn apply_kong_proxy(content: &str, proxy_url: &str) -> String {
    let has_systemd = content.lines().any(|l| {
        let lower = l.trim().to_ascii_lowercase();
        lower.starts_with("environment=")
            || lower.starts_with("execstart=")
            || lower == "[unit]"
            || lower == "[service]"
            || lower == "[install]"
    });

    if has_systemd {
        let mut lines = Vec::new();
        let mut replaced_http = false;
        let mut replaced_https = false;
        let mut replaced_kong = false;

        for line in content.lines() {
            let trimmed = line.trim();
            let lower = trimmed.to_ascii_lowercase();

            if lower.starts_with("environment=") {
                let env_part = trimmed["environment=".len()..]
                    .trim()
                    .trim_matches('"')
                    .trim_matches('\'');
                if let Some((k, _)) = env_part.split_once('=') {
                    let k_low = k.trim().to_ascii_lowercase();
                    if k_low == "http_proxy" {
                        lines.push(format!("Environment=\"HTTP_PROXY={}\"", proxy_url));
                        replaced_http = true;
                        continue;
                    } else if k_low == "https_proxy" {
                        lines.push(format!("Environment=\"HTTPS_PROXY={}\"", proxy_url));
                        replaced_https = true;
                        continue;
                    } else if k_low == "kong_http_proxy" {
                        lines.push(format!("Environment=\"KONG_HTTP_PROXY={}\"", proxy_url));
                        replaced_kong = true;
                        continue;
                    }
                }
            } else if lower.starts_with("http_proxy=") {
                lines.push(format!("HTTP_PROXY=\"{}\"", proxy_url));
                replaced_http = true;
                continue;
            } else if lower.starts_with("https_proxy=") {
                lines.push(format!("HTTPS_PROXY=\"{}\"", proxy_url));
                replaced_https = true;
                continue;
            } else if lower.starts_with("kong_http_proxy=") {
                lines.push(format!("KONG_HTTP_PROXY=\"{}\"", proxy_url));
                replaced_kong = true;
                continue;
            }

            lines.push(line.to_string());
        }

        if !replaced_http {
            lines.push(format!("Environment=\"HTTP_PROXY={}\"", proxy_url));
        }
        if !replaced_https {
            lines.push(format!("Environment=\"HTTPS_PROXY={}\"", proxy_url));
        }
        if !replaced_kong {
            lines.push(format!("Environment=\"KONG_HTTP_PROXY={}\"", proxy_url));
        }

        return lines.join("\n") + "\n";
    }

    // kong.conf key = value format
    let mut lines = Vec::new();
    let mut replaced_proxy = false;

    for line in content.lines() {
        let trimmed = line.trim();
        let delimiter = if trimmed.contains('=') {
            Some('=')
        } else if trimmed.contains(':') {
            Some(':')
        } else {
            None
        };

        if let Some(d) = delimiter {
            if let Some((k, _)) = trimmed.split_once(d) {
                let key = k.trim().to_ascii_lowercase();
                if key == "http_proxy" || key == "https_proxy" || key == "upstream_proxy" || key == "kong_http_proxy" {
                    let indent = line.len() - line.trim_start().len();
                    lines.push(format!("{:indent$}{} = {}", "", k.trim(), proxy_url, indent = indent));
                    replaced_proxy = true;
                    continue;
                }
            }
        }

        lines.push(line.to_string());
    }

    if replaced_proxy {
        return lines.join("\n") + "\n";
    }

    let mut out = Vec::new();
    if !content.trim().is_empty() {
        out.push(content.trim_end().to_string());
    }
    out.push(format!("http_proxy = {}", proxy_url));
    out.push(format!("https_proxy = {}", proxy_url));

    out.join("\n") + "\n"
}

