            || lower.starts_with("shadow_tls_proxy=")
            || lower.starts_with("shadowtls_proxy=")
            || lower.starts_with("upstream_proxy=")
            || lower.starts_with("upstream_proxy:")
            || lower.starts_with("proxy=")
            || lower.starts_with("proxy =")
            || lower.starts_with("proxy:")
            || lower.starts_with("tls_proxy=")
            || lower.starts_with("tls_proxy:")
            || lower.starts_with("target_proxy=")
