pub fn apply_coredns_proxy(content: &str, proxy_url: &str) -> String {
    if let Ok(mut val) = serde_json::from_str::<serde_json::Value>(content) {
        if let Some(obj) = val.as_object_mut() {
            obj.insert("forward".to_string(), serde_json::Value::String(proxy_url.to_string()));
            return serde_json::to_string_pretty(&val).unwrap_or_else(|_| content.to_string()) + "\n";
        }
    }

    let mut lines = Vec::new();
    let mut replaced = false;

    for line in content.lines() {
        let trimmed = line.trim();
        let lower = trimmed.to_ascii_lowercase();

        if lower.starts_with("environment=") {
            let env_part = trimmed["environment=".len()..]
                .trim()
                .trim_matches('"')
                .trim_matches('\'');
            if let Some((k, _)) = env_part.split_once('=') {
                let k_low = k.trim().to_ascii_lowercase();
                if k_low == "coredns_proxy"
                    || k_low == "coredns_http_proxy"
                    || k_low == "http_proxy"
                    || k_low == "https_proxy"
                {
                    if !replaced {
                        lines.push(format!("Environment=\"HTTP_PROXY={}\"", proxy_url));
                        lines.push(format!("Environment=\"COREDNS_PROXY={}\"", proxy_url));
                        replaced = true;
                    }
                    continue;
                }
            }
        }

        if lower.starts_with("http_proxy=")
            || lower.starts_with("https_proxy=")
            || lower.starts_with("coredns_proxy=")
        {
            if !replaced {
                lines.push(format!("HTTP_PROXY=\"{}\"", proxy_url));
                lines.push(format!("COREDNS_PROXY=\"{}\"", proxy_url));
                replaced = true;
            }
            continue;
        }

        if lower.starts_with("forward .") || lower.starts_with("proxy .") {
            if !replaced {
                let indent = line.chars().take_while(|c| c.is_whitespace()).collect::<String>();
                lines.push(format!("{}forward . {}", indent, proxy_url));
                replaced = true;
            }
            continue;
        }

        let clean = lower.replace(' ', "");
        if (clean.starts_with("forward:") || clean.starts_with("forward=")
            || clean.starts_with("proxy:") || clean.starts_with("proxy=")
            || clean.starts_with("http-proxy:") || clean.starts_with("http-proxy=")
            || clean.starts_with("http_proxy:") || clean.starts_with("http_proxy=")
            || clean.starts_with("coredns_proxy:") || clean.starts_with("coredns_proxy="))
            && !clean.starts_with("proxy_url")
        {
            if !replaced {
                if line.contains('=') {
                    lines.push(format!("forward = {}", proxy_url));
                } else {
                    lines.push(format!("forward: {}", proxy_url));
                }
                replaced = true;
            }
            continue;
        }

        lines.push(line.to_string());
    }

    if !replaced {
        if content.contains('=') {
            lines.push(format!("forward = {}", proxy_url));
        } else if content.contains(':') {
            lines.push(format!("forward: {}", proxy_url));
        } else if content.contains('{') {
            lines.push(format!("    forward . {}", proxy_url));
        } else {
            lines.push(format!("forward . {}", proxy_url));
        }
    }

    lines.join("\n") + "\n"
}

