pub fn apply_tinc_proxy(content: &str, proxy_url: &str) -> String {
    if let Ok(mut val) = serde_json::from_str::<serde_json::Value>(content) {
        if let Some(obj) = val.as_object_mut() {
            obj.insert("Proxy".to_string(), serde_json::Value::String(proxy_url.to_string()));
            return serde_json::to_string_pretty(&val).unwrap_or_else(|_| content.to_string()) + "\n";
        }
    }

    let mut lines = Vec::new();
    let mut replaced = false;
    let proxy_directive = if let Ok(parsed) = url::Url::parse(proxy_url) {
        let scheme = parsed.scheme().to_ascii_lowercase();
        if let Some(host) = parsed.host_str() {
            let port = parsed.port_or_known_default().unwrap_or(1080);
            if scheme.starts_with("socks") || scheme == "http" {
                format!("Proxy = {} {} {}", scheme, host, port)
            } else {
                format!("Proxy = \"{}\"", proxy_url)
            }
        } else {
            format!("Proxy = \"{}\"", proxy_url)
        }
    } else {
        format!("Proxy = \"{}\"", proxy_url)
    };

    for line in content.lines() {
        let trimmed = line.trim();
        let lower = trimmed.to_ascii_lowercase();

        if lower.starts_with("environment=") {
            let env_part = trimmed["environment=".len()..]
                .trim()
                .trim_matches('"')
                .trim_matches('\'');
            if let Some((k, _)) = env_part.split_once('=') {
                let k_low = k.trim().to_ascii_lowercase();
                if k_low == "tinc_proxy"
                    || k_low == "tinc_http_proxy"
                    || k_low == "http_proxy"
                    || k_low == "https_proxy"
                {
                    if !replaced {
                        lines.push(format!("Environment=\"HTTP_PROXY={}\"", proxy_url));
                        lines.push(format!("Environment=\"TINC_PROXY={}\"", proxy_url));
                        replaced = true;
                    }
                    continue;
                }
            }
        }

        if lower.starts_with("http_proxy=")
            || lower.starts_with("https_proxy=")
            || lower.starts_with("tinc_proxy=")
        {
            if !replaced {
                lines.push(format!("HTTP_PROXY=\"{}\"", proxy_url));
                replaced = true;
            }
            continue;
        }

        let clean = lower.replace(' ', "");
        if (clean.starts_with("http_proxy:") || clean.starts_with("http_proxy=")
            || clean.starts_with("http-proxy:") || clean.starts_with("http-proxy=")
            || clean.starts_with("http.proxy:") || clean.starts_with("http.proxy=")
            || clean.starts_with("proxy:") || clean.starts_with("proxy=")
            || clean.starts_with("tinc_proxy:") || clean.starts_with("tinc_proxy="))
            && !clean.starts_with("proxy_url")
        {
            if !replaced {
                lines.push(proxy_directive.clone());
                replaced = true;
            }
            continue;
        }

        lines.push(line.to_string());
    }

    if !replaced {
        let is_systemd = lines.iter().any(|l| l.trim().eq_ignore_ascii_case("[Service]"));
        if is_systemd {
            let mut final_lines = Vec::new();
            let mut inserted = false;
            for l in lines {
                final_lines.push(l.clone());
                if !inserted && l.trim().eq_ignore_ascii_case("[Service]") {
                    final_lines.push(format!("Environment=\"HTTP_PROXY={}\"", proxy_url));
                    final_lines.push(format!("Environment=\"TINC_PROXY={}\"", proxy_url));
                    inserted = true;
                }
            }
            return final_lines.join("\n") + "\n";
        } else {
            lines.push(proxy_directive);
        }
    }

    lines.join("\n") + "\n"
}

